import ast, hashlib, json, subprocess
from pathlib import Path
root=Path('/workspace')
runtime=json.loads(subprocess.check_output(['python3',str(root/'tools.py'),'resolve','run://r-001'],text=True))
p=json.loads((root/'proposal.json').read_text())

def validate(value,schema,path='study'):
    t=schema.get('type')
    types={'object':dict,'array':list,'string':str,'boolean':bool}
    if t in types:
        assert isinstance(value,types[t]), (path,'type',t)
    if 'const' in schema:
        assert value == schema['const'], (path,'const')
    if 'enum' in schema:
        assert value in schema['enum'], (path,'enum')
    if isinstance(value,dict):
        assert set(schema.get('required',[])) <= value.keys(), (path,'required')
        props=schema.get('properties',{})
        if schema.get('additionalProperties') is False:
            assert value.keys() <= props.keys(), (path,'unexpected keys')
        for k,v in value.items():
            if k in props: validate(v,props[k],path+'.'+k)
    if isinstance(value,list):
        assert len(value)>=schema.get('minItems',0), (path,'minItems')
        for i,v in enumerate(value): validate(v,schema.get('items',{}),path+f'[{i}]')
    if isinstance(value,str):
        assert len(value)>=schema.get('minLength',0), (path,'minLength')
validate(p['study'],runtime['study_schema'])
assert p['study']['protocol_ref']==runtime['required_study_protocol_ref']
assert p['parent_trial'] in runtime['context']['allowed_observation_ids']
assert set(p['study']['evidence_refs']) <= set(runtime['context']['allowed_observation_ids'])
assert 1<=len(p['variants'])<=4
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert any(v['role']=='candidate' for v in p['variants'])
parent_source=(root/'history_r0027_frozen_none.py').read_text()
source=(root/'candidate.py').read_text()
parent_tree=ast.parse(parent_source); tree=ast.parse(source)
compile(source,str(root/'candidate.py'),'exec')
parent_class=next(n for n in parent_tree.body if isinstance(n,ast.ClassDef) and n.name=='Model')
new_class=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='Model')
parents={n.name:n for n in parent_class.body if isinstance(n,ast.FunctionDef)}
new={n.name:n for n in new_class.body if isinstance(n,ast.FunctionDef)}
preserved=['__init__','_encode','_weights','_logits','_rotation_donors','_event_scales','_normalize_product','_scores_from_product','_product','forward']
for name in preserved:
    assert ast.dump(parents[name])==ast.dump(new[name]), name+' AST changed'
    assert ast.get_source_segment(parent_source,parents[name])==ast.get_source_segment(source,new[name]), name+' source changed'
assert all(name not in new for name in ['_aggregate','_row_targets','_total_targets','_synthetic_total_audit'])
assert not any(isinstance(n,ast.Call) and isinstance(n.func,ast.Attribute) and n.func.attr in ['grad','backward','index_add_'] for n in ast.walk(tree))
allowed={'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib'}
for node in ast.walk(tree):
    if isinstance(node,ast.Import):
        assert all(n.name.split('.')[0] in allowed for n in node.names)
    if isinstance(node,ast.ImportFrom):
        assert node.module.split('.')[0] in allowed
    if isinstance(node,ast.Call) and isinstance(node.func,ast.Name):
        assert node.func.id not in ['eval','exec','open','compile','__import__']
config_node=next(n for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
config=ast.literal_eval(config_node.value)
parent_hash=hashlib.sha256((root/'history_r0027_frozen_none.py').read_bytes()).hexdigest()
assert parent_hash=='4a126d4aacb4a4e1a3600cf9753259a0c433350346d0e663fb3e69887f7b0e94'
baseline_hash=hashlib.sha256((root/'baseline_reference.py').read_bytes()).hexdigest()
assert baseline_hash=='ee10868f589c077b19f57a1fb07702c947c56e970994cdc537ef83ea2b8bc943'
assert (root/'baseline_reference.py').read_bytes()==(root/'history_baseline_din.py').read_bytes()
source_hash=hashlib.sha256(source.encode()).hexdigest()
for v in p['variants']:
    assert v['file']==Path(v['file']).name and v['file'].endswith('.py')
    assert v['config']==config
    assert v['role'] in ['candidate','control']
    v['note'] += ' Frozen candidate SHA256 '+source_hash+'. Checked parent hash, identical __init__/nine forward-helper methods (AST and exact source), CONFIG, numeric imports, syntax and study schema. Reproduction entry: host consumes proposal.json with this standalone module; no local training interface is exposed.'
required_cards={x['id'] for x in runtime['retrieved_evidence']['cards'] if x.get('knowledge_type')=='industry'}
assert required_cards <= {x['knowledge_id'] for x in p['knowledge_assessments']}
for k in p['knowledge_assessments']:
    assert k['decision'] in ['used','considered','rejected','unresolved']
    assert set(k['variant_names']) <= {v['name'] for v in p['variants']}
(root/'proposal.json').write_text(json.dumps(p,indent=2,allow_nan=False)+'\\n')
print(json.dumps({'study_schema':'passed','proposal_contract':'passed','source_and_ast_preserved':preserved,'config_matches_variant':True,'parent_hash_matches_receipt':True,'baseline_hash_matches_receipt':True,'no_extra_backward_or_row_aggregation':True,'candidate_sha256':source_hash,'numeric_imports_only':True,'retrieved_industry_cards_documented':sorted(required_cards),'torch_or_training_executed':False},indent=2))
PY"

